/* ============================================================
   LangLab — TIẾNG NHẬT: khoá học N5 → N2 (A1 → B2), tự soạn cho người Việt theo khung JLPT
   và trình tự sư phạm quen thuộc (chào hỏi → chỉ định → thời gian → động từ ます → tính từ → tồn tại → đếm → て形 → ない形 → 辞書形 → た形 → 普通形…).
   Quy ước văn bản: furigana ghi 漢字[かな]; các từ trong câu tách bằng dấu cách để bấm tra được (hiển thị sẽ ghép liền).
   Từ vựng: jp (kanji nếu có), kana, romaji, vi, pos, g (nhóm động từ 1/2/3), note.
   Nhân vật: クアン (Quân, sinh viên Việt Nam ở Hà Nội), 田中 (Tanaka), 鈴木先生 (cô Suzuki), 山田 (Yamada), リン (Linh).
   ============================================================ */
