        { form:'普通形 + でしょう (phỏng đoán)', vi:'có lẽ …, chắc là …', note:'Dựa trên căn cứ, độ chắc cao; N/なA bỏ だ: 明日は雨でしょう, 静かでしょう. Thường với たぶん, きっと. Thân mật: 〜だろう. Khác 〜でしょう？ (hỏi xác nhận, N5).', ex:{ jp:'天気予報[てんきよほう] に よる と 、 明日[あした] は 台風[たいふう] が 来[く]る でしょう 。', vi:'Theo dự báo, ngày mai có lẽ bão sẽ đến.' } },
        { form:'普通形 + かもしれません', vi:'có thể …, không chừng …', note:'Độ chắc thấp (~50%); N/なA bỏ だ. Thường với もしかしたら / もしかすると. Thân mật: 〜かもしれない / 〜かも.', ex:{ jp:'もしかしたら 、 風邪[かぜ] を ひいた の かも しれません 。', vi:'Không chừng tôi bị cảm rồi.' } },
        { form:'きっと ・ たぶん ・ もしかしたら', vi:'chắc chắn · có lẽ · không chừng', note:'Mức chắc chắn giảm dần: きっと〜でしょう / たぶん〜でしょう / もしかしたら〜かもしれません. 必ず (nhất định) dùng cho ý chí, lời hứa.', ex:{ jp:'田中[たなか]さん は たぶん 来[く]る でしょう 。 でも 、 山田[やまだ]さん は 来[こ]ない かも しれません 。', vi:'Tanaka có lẽ sẽ đến. Nhưng Yamada thì không chừng không đến.' } }
